  // 2026-09-29 币种口径修正：腾讯控股与泡泡玛特的经营报表以人民币计价，而股价、逐年分红
  // 与期末卖出价值必须用港元。此前把人民币每股盈利直接标为港元 EPS，未做汇率折算，
  // 使这两只的基准 IRR 被系统性低估。此处按与其他港股标的相同的固定研究汇率重算：
  // 1港元 = 0.86015元人民币（2026-09-23 外汇局中间价口径），2027—2036 固定该汇率。
  for (const stock of stocks.filter(item => ["00700", "09992"].includes(item.code))) {
    stock.model.assumptionNote = `${stock.model.assumptionNote} 币种口径已修正：公司报表以人民币计价，而股价、EPS、逐年分红与期末卖出价值全部采用港元，人民币每股盈利按固定 1港元=0.86015元人民币 换算为港元EPS；EPS 的币种为本次唯一调整项，两阶段增速、分红率与退出PE为研究情景假设。该汇率是研究假设，不是当日可成交报价；未计未来汇率变化，若人民币对港元贬值，港元盈利与派息能力随之下降。已实施分红不计入买入后的未来现金流。`;
  }

  // 全池统一为十年股东现金流 IRR（shareholder-irr-v1）：
  // 起始 EPS、两阶段增速、分红率与退出 PE 为研究情景假设，模型只输出 IRR、差额与达标参考价。
  function studyModel(study) {
    const unit = study.modelCurrency || "元";
    const financialPeriod = (study.facts || []).some(row => String(row[2]).includes("2026H1")) ? "2026H1" : "见财务报告";
    const rateLabel = `${(study.requiredReturn * 100).toFixed(1)}%`;
    return {
      ...study,
      profitForecast: {
        year: study.forecastYear || 2026,
        note: study.forecastNote,
        scenarios: study.assumptions.map(assumption => ({
          name: assumption.name,
          profit: assumption.profit,
          eps: `${assumption.eps.toFixed(2)}${unit}`,
          pe: `${(study.price / assumption.eps).toFixed(1)}倍`,
          reason: assumption.reason
        }))
      },
      model: {
        version: "shareholder-irr-v1",
        currency: unit,
        requiredReturn: study.requiredReturn,
        reviewedAt: MODEL_REVIEW_DATE,
        financialPeriod,
        assumptionNote: "起始EPS、两阶段增速、分红率与退出PE为研究情景假设，未因行情变化调整盈利预测。",
        requiredReturnReason: `研究回报要求 ${rateLabel}，反映${study.requiredReturnReason}；该要求是投资门槛，不是模型解出的IRR。`,
        method: "每买入1股，逐年领取现金分红并在第10年末卖出，求股东现金流IRR。分红按前一年度EPS估算，首年从2026年预测EPS起算；持有年度按t=1…10表示，不把年度近似当成实际派息日。完整股权PE与归母EPS配套，净现金不另外相加。银行、保险的EPS与PE仅是简化情景，必须同时检查资本充足率、资产质量或偿付能力。",
        dividendNote: "首年分红按起始EPS×分红率估算，属模型预测；正式派息方案公布后只替换对应预测，不重复加计。已实施分红不计入买入后的未来现金流。",
        assumptions: study.assumptions.map(assumption => ({
          ...assumption
        }))
      }
    };
  }

