        masterViews:[{name:"巴菲特视角",verdict:"先拆客户资金与所有者收益",text:"用户入口有经济价值，却不能用金融企业合并经营现金直接估所有者收益。17.79元下应以跨周期券商利润、净资本需求与基金保有费收入定价值；若高活跃度才支撑19倍PE，安全边际不足。"},{name:"芒格视角",verdict:"警惕牛市把周期当护城河",text:"平台、品牌与投研工具可形成正反馈；但行情亢奋会抬高交易收入，也会让投资者误判增长质量。反向检查熊市交易量、两融坏账、费率压缩和客户资金错觉。"},{name:"段永平视角",verdict:"入口易懂，十年现金不够易懂",text:"用户选择天天基金和券商服务的原因可解释，但未来现金受资本市场和监管左右。只有能用保守交易量与基金净收入算清长期可分配现金，才有理由讨论价格；不因PE低于互联网平台就忽略能力圈边界。"},{name:"散户乙视角",verdict:"不是稳定分红回本资产",text:"账面现金中客户资金和券商营运资本不能视为自己的安全垫。中期不派息，现价依赖利润和估值回归而非确定股息回本；不应为景气弹性加杠杆。"},{name:"韦尔奇视角",verdict:"组织执行强，须考核客户质量",text:"技术和渠道把低成本服务规模化，但应按留存、有效基金保有、合规事件、券商净资本回报和服务体验考核团队，而非基金交易额或市场热度。"}],
        questions:["证券经纪净收入在成交量下降时的韧性","非货基金保有量及费率后的净收入","券商净资本、母公司可分配利润与分红能力","两融坏账、自营波动和合规处罚","股本与股权激励的每股影响"],risks:["证券市场低迷导致利润回撤","基金销售费率下行","两融信用及自营投资损失","监管资本或合规处罚","交易流量转向竞品平台"],
