        price:16.37,priceDate:"2026-09-30",marketCap:"约2,499亿元（按152.67亿股估算）",confidence:"中等偏低",valuation:"分红积极，但航运利润不能按当前运价永续",
        thesis:"全球航线网络、船队规模、码头和物流衔接带来运营优势；但运价主要由全球贸易、船舶供给与绕航共同决定，新船交付和地缘缓和都可能压缩利润。必须以完整航运周期检验分红与再投资能力。",
        conclusion:"16.37元对应9.34倍TTM PE、1.07倍PB，看似低估却处于运价和利润波动行业。2026H1归母约134.19亿元同比下降23.48%，董事会拟派中期每股0.43元。基准正常化利润人民币200亿元及未来派息均为条件假设；船队订单、租船承诺与逆周期现金尚未桥接，暂停正式排名。",
        industryStatus:["集装箱航运运力供给由多年之前的造船订单决定，需求与贸易政策变化更快，供需错配会把少量运价波动放大为利润波动。","航线绕行和港口拥堵短期收紧有效供给；若航路恢复或新船集中交付，同一船队可能经历低运价。码头业务能提供稳定性，但无法对冲全部海运周期。"],
