        debate:[{title:"低PE代表安全边际吗？",body:"TTM盈利仍可能包含地缘扰动与阶段性运价。应先用正常与低运价年份核可分配现金，再看16.37元是否便宜。"},{title:"分红能否穿越新船周期？",body:"中期0.43元有实际方案支持，但未来船舶交付、租船与环保改造需求不确定。历史高派息不能直接外推十年。"},{title:"航线网络护城河有多宽？",body:"规模与端到端物流可以改善利用率和客户关系，却不能脱离全球集运供给周期独立定价。"}],
