        masterViews:[{name:"巴菲特视角",verdict:"用全周期所有者收益而非低PE",text:"船队有价值，也需要造船、维护、燃料效率和租船资本。16.37元对应9.34倍TTM不能证明安全边际；应以低运价年份仍能保有的所有者收益估值，并防止把一次高派息当永续。"},{name:"芒格视角",verdict:"反向测试绕航与订单共振",text:"市场容易把地缘导致的有效运力紧张当长期竞争优势。若航道恢复同时新船交付、贸易疲弱，利润和股息会一起承压；管理层在景气高点造船的激励尤其要审视。"},{name:"段永平视角",verdict:"现金多不等于生意容易预测",text:"公司分红可见，全球网络也有客户价值，但十年现金取决于自己无法控制的运价和造船周期。若只能用高景气利润才能讲通买入价格，就不符合先看懂生意、再谈价格的纪律。"},{name:"散户乙视角",verdict:"股息诱人，须防周期尾部",text:"中期0.43元对现金回收有帮助，但并不构成每年保证。先检验低运价、船队更新和债务承诺叠加时能否不借钱派息；不借杠杆追逐静态高股息。"},{name:"韦尔奇视角",verdict:"聚焦装载率与资本纪律",text:"船队调度、客户服务和码头协同体现执行力，但应看单位箱成本、准班率、装载率和新船全周期回报；组织不应以运力规模奖励扩张。"}],
