  septemberStudies.push({
    code:"601336",slug:"new-china-life",name:"新华保险",researchDate:"2026-10-01",industry:"寿险与资产负债管理",price:56.35,shares:31.195466,pe:3.97,hurdle:.125,confidence:"有限",
    valuation:"低报表PE需要穿透投资收益、精算假设与监管资本",thesis:"续期保费与期交业务形成长期客户关系，但寿险是跨周期资产负债匹配生意，不是把保费直接变成股东自由现金。投资收益、保证成本、资本要求和服务质量共同决定普通股价值。",
    conclusion:"56.35元对应3.97倍TTM PE、1.422倍PB，按A价乘A/H总股本与内含价值比较约0.566倍。折价值得研究，却不能直接认定低估：H1投资业绩占税前利润约67.5%，核心偿付能力降至126.21%。基准以240亿元正常化盈利、25%分配和7倍成熟退出检验，不延续近期资本市场高收益；现价优先级应由下方条件收益及风险证据决定。",
    industryStatus:["寿险既提供保障，也承接长久期储蓄需求；低利率环境下新钱再投资收益下降，存量负债保证成本与久期匹配是核心。分红险可以分担部分收益波动，但不是把全部风险转给客户。","原保费使用旧保险准则，保险服务收入与保险服务业绩使用新准则，不能把两者混作营收增长或自由现金；新业务价值依赖精算假设与持有资本成本，属于估计而非到账资金。"],
    companyStatus:["2026H1原保费1295.70亿元、同比6.9%；长期险首年期交326.12亿元、同比27.7%，续期884.61亿元、同比12.2%；13/25个月继续率97.5%/93.6%，退保率0.7%。这些指标支持业务质量改善，但需后续同口径验证。","H1归母227.93亿元、同比54.0%；保险服务收入264.42亿元。利源分析中保险服务业绩及其他86.62亿元、投资业绩179.61亿元，均为税前拆分；不能将86.62当税后归母，或把投资业绩全部剔除为一次性。","内含价值3103.84亿元、较年末增7.8%；扣资本成本后NBV69.16亿元、同比11.9%。但扣前NBV72.79亿元低于上年79.15亿元，资本成本由17.33降为3.64亿元，净NBV改善包含资本成本变化，不能全部归功销售增长。","核心/综合偿付能力126.21%/195.74%，年末135.11%/210.47%；最低资本由1490.32升至1621.28亿元。H1年化净/总投资收益率2.6%/6.7%，净收益率下降而总收益率提升，权益兑现不能永久外推。","2025末期每股2.06元与中期0.67元分开，全年合计2.73元；2026中期拟每股0.73元、约22.77亿元，仍待股东会批准。模型不把未获批准股息额外加到全年预测，也不重复计入已实施历史派息。"],
    facts:[["A股价格 / PE / PB","56.35元 / 3.97 / 1.422倍（2026-09-30）"],["A/H总普通股本","31.195466亿股；不是A股单独股数"],["H1归母 / 保险服务收入","227.93 / 264.42亿元"],["H1投资业绩 / 税前利润","179.61 / 266.23亿元，约67.5%"],["内含价值 / 净NBV","3103.84 / 69.16亿元"],["扣资本成本前NBV","72.79亿元，同比约−8.0%"],["核心 / 综合偿付能力","126.21% / 195.74%"],["净 / 总投资收益率","2.6% / 6.7%，均为H1年化指标"],["EV主要假设","风险贴现8.5%；非投连未来投资回报4.0%"],["EV利率压力","投资回报−50bp：有效业务价值834.39→427.09亿元"],["母公司可分利润锚","H1净利217.36亿元、期末未分配1336.57亿元；非自由现金"],["中期股息状态","每股0.73元为拟议，待股东会批准"]],
    debate:[{title:"3.97倍PE是否已经充分便宜？",body:"近期利润包含强投资表现，正常化240亿元对应约7.32倍起点PE，明显高于报表倍数。低PE不是对持续盈利或可分现金的核实；股市反转与再投资利率下降可能共同压低利润。"},{title:"0.566倍内含价值是否可兑现？",body:"该值按A价乘全体普通股数计算，不是A/H两地实际市值加总。EV包含未来业务估计，4.0%投资回报与资本口径敏感；减50bp后有效业务价值减少407.30亿元，不是整个EV减半，更不是必然损失。"},{title:"保费和账面现金能否支持高分红？",body:"保费首先对应保单负债，投资资产与监管资本不是可任意分给普通股的现金。以已披露分红决议、母公司利润及资本缓冲判断分配能力；不采用集团经营现金减设备的工业企业公式。"}],
    profits:[160,240,340],
    growth:[[-.10,-.05,0,0,.01,.01,.01,.01,.01,.01],[.04,.04,.035,.03,.03,.025,.025,.02,.02,.02],[.06,.06,.05,.05,.04,.035,.03,.03,.025,.025]],
    payouts:[[.20,.20,.20,.20,.20,.20,.20,.20,.20,.20],[.25,.25,.25,.25,.25,.25,.25,.25,.25,.25],[.30,.30,.30,.30,.30,.30,.30,.30,.30,.30]],exits:[5,7,9],
    reasons:["投资回报下降及资本压力叠加，利润160亿元仍在随后两年受压；20%分配亦非保证。","不沿用6.7%总投资收益率，把240亿元作为跨周期税后归母代理；期交与续期稳健增长，成熟增速降至2%，25%分配须有资本支持。","新业务质量、投资回报和负债成本共同改善，340亿元仍不等于H1翻倍；30%分配与9倍退出均需持续ROE及资本缓冲证明。"],
    forecastNote:"160/240/340亿元是2026正常化税后归母研究锚，不是公司年度预测；2025归母362.8亿元与H1227.93亿元只能作历史参照。基准低于2025约34%，也低于H1简单年化约47%，体现投资高收益不永续；不是把179.61亿元投资业绩全剔除，保险业务也需要持续投资回报。未完成逐项精算盈利桥接，可信度有限；不能用扣非TTM419.5亿元当全年正常利润。EPS=利润÷31.195466亿A/H总普通股，未来股数固定。",
    hurdleReason:"12.5%为研究者主观年回报要求，补偿长期保证成本、权益波动、精算假设、监管资本及治理的不透明尾部；寿险分配约束高于普通消费公司。不同于公司EV使用的8.5%精算风险贴现率，不以二者相等或历史低PE代替判断。",
    dividendView:"2025中期0.67元、末期2.06元合计2.73元/约85.16亿元，对362.8亿元归母约23.47%；不是只用末期64.26亿元算全年分配率。基准25%分配60亿元为相近量级条件研究，不是公司承诺；2026拟中期0.73元不额外叠加，批准与A股登记日待跟踪。保险资金、客户红利和股东红利不得混淆。",
    moat:["长期保单存量与续期关系提供客户沉淀，但服务、继续率和退保行为决定其可持续性。","个险队伍、银保渠道与长期投资能力有规模优势，销售费用与渠道竞争也会消耗价值。","资产负债匹配与风险定价能力比保费规模更重要；不把监管牌照当无限定价权。"],
    views:[
      ["巴菲特","承保与资本纪律优先，低PE不能替代所有者收益","保险经验不能照搬成寿险浮存金免费的结论。新华的保单有保证与分红义务，179.61亿元投资业绩是税前利源，不能全部视为可提取的普通股现金。56.35元对240亿元正常化利润约7.32倍，价格有研究空间，但核心资本126.21%且下降，25%分配要在新业务占用资本后仍成立。框架下只有负债成本低于可持续投资回报、管理层宁可少卖也不牺牲价值、母公司持续产生可分利润与现金，才提高持有优先级。若新业务只靠高佣金、卖高保证产品扩大规模，或收益主要依赖卖出股票，应降低利润与退出倍数。后续以低投资回报下资本缓冲和实际普通股派息检验，而非仅看总保费或EV折价。"],
      ["芒格","先联合检验利差损、退保和资本压力","寿险最危险的认知是把3.97倍PE、0.566倍EV与利润增长拼成没有风险的故事。投资回报假设降50bp，有效业务价值从834.39降至427.09亿元，说明长期小误差会放大；这并不是整个EV减半。若低利率、权益下跌与渠道激励驱动不适当销售同时出现，利润、继续率和资本可能同步受损。56.35元下应先看160亿元起点再下滑、20%分配和5倍退出能否承受，而非执着牛市利润。净NBV增长含资本成本变化，管理层解释是否坦诚很重要。能及时报告错配、约束高保证产品和佣金激励，才提高评级；若用精算估值替代偿付与现金证据，宁可等待更清楚的安全边际。"],
      ["段永平","看得懂保单承诺，才讨论便宜与否","新华向客户卖的是长期保障与储蓄安排，研究不能只看投资团队在股市赚了多少。客户是否得到符合需求的产品、理赔是否可靠、销售有没有误导，影响未来退保、声誉和续期现金；这些比一时保费排名更接近生意模式与文化。56.35元的低报表PE仍要求自己理解保证成本、分红机制、资产负债匹配及未来真正属于股东的现金。若能在保守投资回报下毛估估出240亿元盈利与25%分配，且治理本分、资本充足，可以继续研究；若必须猜股市或相信4.0%回报不变才能证明便宜，就可不买。后续重点观察服务质量、持续续期与资本纪律；这是框架推演，不表示段永平本人对新华保险有已核实的持仓或买卖意见。"],
      ["散户乙","分红现金不等于低PE利润，先守最坏情况","56.35元按240亿元正常化利润和25%派息，对应起点预测每股约1.92元、约3.4%的现金收益率；不是拿3.97倍PE倒推十年分红就能回本。即使内含价值折价，未来分配仍受监管资本、投资损失与保证义务约束。十年分红能否覆盖成本要看同一引擎的现金路径，不把第十年出售所得称为分红收回成本。160亿元起点、20%派息再叠加前两年利润下降，是应当先看的压力情景；不融资、不依赖浮盈填补生活资金。只有低景气时仍有普通股派息且无需侵蚀资本，才提高积累价值；若分配不断下降、资本逼近缓冲或只能靠卖股维持，应停止把它当稳定现金资产。"],
      ["韦尔奇","渠道质量和风险责任比销售榜更重要","经营评价应把个险、银保与投资分清责任：期交增长27.7%很好，但要追踪获客成本、继续率、投诉理赔及新业务资本成本，不能以净NBV增长掩盖扣前NBV下降。投资部门不能只按收益率奖励，还应负责久期错配、回撤与资本消耗；客户服务部门要用实际理赔体验和续保质量证明执行。56.35元和25%分配是独立财务假设，韦尔奇框架不能提供个人目标价。若渠道从规模考核转向客户价值、跨部门反馈坦诚且单位资本产出改善，可提高经营质量评价；若销售冲量与投资冒险同时被奖励，应降低评价。后续检验同口径扣前/扣后NBV、继续率以及资本效率，不用管理口号替代证据。"]],
    capital:"保险公司不采用经营现金减设备作为普通股FCF：保费、投资资产和现金首先支持保单负债。H1核心资本2046.24亿元、实际资本3173.56亿元、最低资本1621.28亿元，核心/综合充足率126.21%/195.74%较年末下降；监管资本不是现金。母公司H1净利217.36亿元、未分配利润1336.57亿元是法律利润锚，不证明全部可立即汇付。拟0.73元中期股息约22.77亿元仍待批准；2025全年中期加末期约85.16亿元是历史分配锚。基准240×25%=60亿元量级低于历史，但尚未建立未来资本释放与现金支出的逐年桥接，故仅有限可信度条件情景。低利率和新业务资本增加时必须先下修派息，而不是默认靠融资分红。",
    shareNote:"总普通股3,119,546,600股=31.195466亿股，包含A/H，以A价×总数计算只是单一A价估值代理，不是两地实际市值合计。EPS不采用A股单独分母，不计未来发行、回购或股权激励。",
    conditions:"240亿元跨周期盈利须由保险服务与可持续投资利差共同支持，25%分配以母公司可分利润、实际现金和监管资本缓冲相容为前提；没有逐年精算及资本模型，保留有限可信度，不把条件排名解释为现价推荐。长期利差恶化、资本缓冲继续缩小或客户品质下降，须同时下修利润、分配与退出倍数。",
    questions:["扣前NBV与单位资本产出是否同步改善，而非仅资本成本下降？","净投资收益与负债保证成本是否匹配，久期与权益风险是否受控？","资本缓冲下降时普通股股息是否仍有真实现金与母公司利润支持？","期交、继续率、理赔服务与费用率能否证明客户价值提升？"],risks:["长期利率下降与保证成本形成利差损","权益回撤、精算假设与资本成本重估","渠道费用、误导销售及退保风险","监管资本约束压缩普通股派息"],
    pdf:"https://pdf.dfcfw.com/pdf/H2_AN202608261828487984_1.pdf",date:"2026-08-26",locator:"PDF34—35页利源与偿付能力；45—48页EV假设和敏感性；股份及利润分配章节",extra:[["数据与参数核验","2026-10-01","reports/stocks/新华保险-601336-数据核验.md"]]
  });
