  cmb.conclusion = "零售存款和财富管理有长期价值，当前研究仍受信用尾部和监管资本约束；按已披露35%附近的现金分配设定基准，盈利和增长沿用原研究。收益、差额与参考价均由下方同一模型重新计算，不以低PB自动认定低估。";
  const eastMoney = stocks.find(s=>s.code === "300059");
  eastMoney.model.assumptions.forEach((a,i)=>{ a.payout = [.08,.10,.15][i]; });
  eastMoney.dividendView = "2026中期不分配，2025年度每股0.10元已除息，不重复计入未来现金。按普通股实际分配量级与母公司经营现金，基准从20%降至10%，悲观8%、乐观15%为研究情景；子公司净资本和现金上缴仍须跟踪。";
  eastMoney.conclusion = "财经流量和财富管理渠道具有价值，但盈利受交投、费率和自营波动影响。已补母公司现金及证券子公司2025净资本，基准现金分配从20%降至10%后参与中等可信度情景比较；不把客户资金当股东现金，收益与参考价按同一模型重算。";
  const xiaomiRanking = stocks.find(s=>s.code === "01810");
  xiaomiRanking.dividendView = "公司不派2026中期股息，十年条件模型保持零现金股息，不预设未来恢复年份。以零股息终值型参与同口径研究排序，所有现金回报来自第十年卖出，可信度有限；回购不当分红、不另加收益。";
  xiaomiRanking.conclusion = "消费电子与汽车业务的经营路径仍需验证；本轮维持十年零股息，以终值型条件情景参与研究排序。现金回报完全依赖第十年出售，不代表终值已获验证，也不构成现价买入结论。";
  window.STOCK_RESEARCH.meta.updatedAt = "2026-10-01";
